using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using SysAdminAssistant.Core;
namespace SysAdminAssistant.Infrastructure;
public sealed class InvoiceStore(DatabaseFactory factory)
{
    public static InvoiceData Data(InvoiceRecord r)=>JsonSerializer.Deserialize<InvoiceData>(r.Json,RemoteData.Json)??throw new InvalidDataException(global::SysAdminAssistant.Core.ProductText.Get("Повреждена карточка счета"));
    public async Task<InvoiceView[]> List(CancellationToken token=default,int? paymentId=null){await using var db=factory.Create();var records=await db.InvoiceRecords.AsNoTracking().Where(x=>paymentId==null||x.PaymentId==paymentId).OrderBy(x=>x.Status=="Review"?0:1).ThenByDescending(x=>x.Id).Take(2000).ToArrayAsync(token);var files=await db.InvoiceAttachments.AsNoTracking().Select(a=>new{a.Id,a.DocumentId,a.Name,a.MediaType,Bytes=a.Data.Length}).ToArrayAsync(token);return records.Select(r=>new InvoiceView(r.Id,r.Revision,r.Status,r.PaymentId,Summary(r),files.Where(f=>f.DocumentId==r.Id).Select(f=>new InvoiceFile(f.Id,f.Name,f.MediaType,f.Bytes)).ToArray())).ToArray();}
    static InvoiceData Summary(InvoiceRecord r){var d=Data(r);d.RawText="";d.MailBody="";return d;}
    public async Task<InvoicePaymentLink[]> Links(CancellationToken token){await using var db=factory.Create();var records=await db.InvoiceRecords.AsNoTracking().Where(x=>x.PaymentId!=null).Select(x=>new{x.Id,PaymentId=x.PaymentId!.Value}).ToArrayAsync(token);var files=(await db.InvoiceAttachments.Select(x=>x.DocumentId).Distinct().ToArrayAsync(token)).ToHashSet();return records.GroupBy(x=>x.PaymentId).Select(g=>new InvoicePaymentLink(g.Key,g.Any(x=>files.Contains(x.Id)))).ToArray();}
    public async Task<InvoiceView> Detail(int id,CancellationToken token=default){await using var db=factory.Create();var r=await db.InvoiceRecords.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,token)??throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Счет не найден"));var files=await db.InvoiceAttachments.Where(a=>a.DocumentId==id).Select(a=>new InvoiceFile(a.Id,a.Name,a.MediaType,a.Data.Length)).ToArrayAsync(token);return new(r.Id,r.Revision,r.Status,r.PaymentId,Data(r),files);}
    public async Task<int> Ingest(string key,InvoiceData data,string digest,string fileName,string type,byte[] bytes,bool trusted,int weekend,CancellationToken token=default)
    {
        await using var db=factory.Create();await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,token);
        var business=InvoiceRecognition.BusinessKey(data);var existing=await db.InvoiceRecords.FirstOrDefaultAsync(x=>x.Key==key||digest!=""&&x.Digest==digest,token);
        if(existing==null&&business!=""){var candidates=await db.InvoiceRecords.Where(x=>x.BusinessKey==business).ToArrayAsync(token);existing=candidates.OrderBy(x=>x.PaymentId==null?1:0).ThenBy(x=>x.Id).FirstOrDefault(x=>{var old=Data(x);return old.BankAccount==data.BankAccount&&old.BankCode==data.BankCode&&old.Correspondent==data.Correspondent;});if(existing==null&&candidates.Length>0)data.Issues=data.Issues.Append("Тот же счёт, но другие реквизиты: требуется отдельное подтверждение").ToArray();}
        if(existing!=null){var old=Data(existing);if(existing.Status=="Review"&&old.ExtractionError.Length>0&&data.ExtractionError.Length==0){data.Sender=old.Sender;data.Subject=old.Subject;data.ReceivedUtc=old.ReceivedUtc;data.SenderDateUtc=old.SenderDateUtc;data.MailBody=old.MailBody;data.SenderAuthenticated=old.SenderAuthenticated;existing.Json=JsonSerializer.Serialize(data,RemoteData.Json);existing.BusinessKey=InvoiceRecognition.BusinessKey(data);existing.Revision++;}if(bytes.Length>0&&!await db.InvoiceAttachments.AnyAsync(a=>a.DocumentId==existing.Id&&a.Digest==digest,token)&&await db.InvoiceAttachments.CountAsync(a=>a.DocumentId==existing.Id,token)<8){db.InvoiceAttachments.Add(new(){DocumentId=existing.Id,Name=fileName,MediaType=type,Digest=digest,Data=bytes});await db.SaveChangesAsync(token);}await db.SaveChangesAsync(token);await tx.CommitAsync(token);return -existing.Id;}
        var sameNumber=await db.InvoiceRecords.AsNoTracking().OrderByDescending(x=>x.Id).Take(2000).ToArrayAsync(token);
        var lastApproved=sameNumber.FirstOrDefault(r=>r.Status is "Added" or "Linked"&&(data.TaxId.Length>0?Data(r).TaxId==data.TaxId:Data(r).Supplier.Equals(data.Supplier,StringComparison.OrdinalIgnoreCase)));
        if(lastApproved!=null){var prior=Data(lastApproved);if(prior.BankAccount!=data.BankAccount||prior.BankCode!=data.BankCode||prior.Correspondent!=data.Correspondent||prior.Kpp!=data.Kpp)data.Issues=data.Issues.Append("Реквизиты отличаются от последнего принятого счёта поставщика").ToArray();}
        if(sameNumber.Any(r=>{var x=Data(r);return x.Supplier.Equals(data.Supplier,StringComparison.OrdinalIgnoreCase)&&x.Number==data.Number&&x.InvoiceDate==data.InvoiceDate;}))data.Issues=data.Issues.Append("Есть счет с этим номером и другой суммой/валютой").ToArray();
        data.SenderAuthenticated=trusted;
        if(!trusted)data.Issues=data.Issues.Append("Отправитель или SPF/DKIM не подтверждены для автоматической обработки").ToArray();
        if(data.RecurringCandidateId==null&&data.Supplier.Length>2){var payments=await db.Payments.Where(p=>p.Repeat!=RepeatPeriod.None).ToArrayAsync(token);data.RecurringCandidateId=payments.FirstOrDefault(p=>p.Title.Contains(data.Supplier,StringComparison.OrdinalIgnoreCase)||data.Supplier.Contains(p.Title,StringComparison.OrdinalIgnoreCase))?.Id;}
        if(data.RecurringCandidateId!=null)data.Issues=data.Issues.Append("Возможно пересечение с повторяющимся платежом: выберите период или оставьте разовым").ToArray();
        var record=new InvoiceRecord{Key=key,BusinessKey=business,Digest=digest,Json=JsonSerializer.Serialize(data,RemoteData.Json)};db.InvoiceRecords.Add(record);await db.SaveChangesAsync(token);
        if(bytes.Length>0)db.InvoiceAttachments.Add(new(){DocumentId=record.Id,Name=fileName,MediaType=type,Digest=digest,Data=bytes});
        if(data.Issues.Length==0){var payment=Payment(data,record.Id);db.Payments.Add(payment);await db.SaveChangesAsync(token);record.PaymentId=payment.Id;record.Status="Added";}
        await db.SaveChangesAsync(token);await tx.CommitAsync(token);return record.Id;
    }
    static Payment Payment(InvoiceData d,int id)=>new(){Title=d.Supplier+" · счёт "+d.Number,DueDate=d.DueDate!.Value,AmountKopecks=d.Currency=="RUB"?d.AmountCents:null,Repeat=RepeatPeriod.None,Notes=$"Из почты · {d.AmountCents/100m:0.00} {d.Currency} · ИНН {d.TaxId} · [SAA-INVOICE:{id}]"};
    public async Task Approve(InvoiceApproval request,CancellationToken token=default)
    {
        await using var db=factory.Create();await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,token);var r=await db.InvoiceRecords.SingleOrDefaultAsync(x=>x.Id==request.Id,token)??throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Счёт не найден"));if(r.Revision!=request.Revision||r.Status!="Review")throw new InvoiceConflictException(global::SysAdminAssistant.Core.ProductText.Get("Счёт уже изменён. Откройте заново"));var d=request.Data;var original=Data(r);
        if(string.IsNullOrWhiteSpace(d.Supplier)||d.Supplier.Length>200||d.Number.Length is <1 or >100||d.AmountCents is null or <=0 or >99999999999999||d.Currency.Length!=3||!d.Currency.All(char.IsAsciiLetterUpper)||d.InvoiceDate==null||d.DueDate==null||d.DueDate<d.InvoiceDate||d.BankAccount.Length>100||d.BankCode.Length>100||d.TaxId.Length>100||d.Kpp.Length>100||d.Correspondent.Length>100||d.Purpose.Length>4000)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Проверьте поставщика, номер, сумму, валюту, даты и реквизиты"));
        d.SenderAuthenticated=original.SenderAuthenticated;d.Sender=original.Sender;d.Subject=original.Subject;d.ReceivedUtc=original.ReceivedUtc;d.SenderDateUtc=original.SenderDateUtc;d.MailBody=original.MailBody;
            d.Issues=d.Issues.Concat(original.Issues.Where(x=>x.Contains("изменённые банковские реквизиты",StringComparison.OrdinalIgnoreCase)||x.StartsWith("Реквизиты отличаются",StringComparison.OrdinalIgnoreCase)||x.StartsWith("Тот же счёт",StringComparison.OrdinalIgnoreCase))).Distinct().ToArray();d.RawText=original.RawText;d.OcrConfidence=original.OcrConfidence;d.ExtractionError=original.ExtractionError;d.Extraction=original.Extraction;d.TemplateId=original.TemplateId;d.Issues=[];
        if(request.LinkPaymentId is int id){var p=await db.Payments.SingleOrDefaultAsync(x=>x.Id==id,token)??throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Платёж не найден"));if(p.Repeat!=RepeatPeriod.None&&request.Period==null)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Укажите период повторяющегося платежа"));r.PaymentId=id;d.LinkedPeriod=request.Period??p.DueDate;r.Status="Linked";}
        else {
            var key=InvoiceRecognition.BusinessKey(d);var others=await db.InvoiceRecords.AsNoTracking().Where(x=>x.Id!=r.Id&&x.BusinessKey==key&&key!="").ToArrayAsync(token);var duplicate=others.OrderBy(x=>x.PaymentId==null?1:0).ThenBy(x=>x.Id).FirstOrDefault(x=>{var old=Data(x);return old.BankAccount==d.BankAccount&&old.BankCode==d.BankCode&&old.Correspondent==d.Correspondent;});
            if(duplicate!=null){r.PaymentId=duplicate.PaymentId;r.Status="Duplicate";d.DuplicateOfId=duplicate.Id;}else{var p=Payment(d,r.Id);db.Payments.Add(p);await db.SaveChangesAsync(token);r.PaymentId=p.Id;r.Status="Added";}}
        r.Json=JsonSerializer.Serialize(d,RemoteData.Json);r.BusinessKey=InvoiceRecognition.BusinessKey(d);r.Revision++;await db.SaveChangesAsync(token);await tx.CommitAsync(token);
    }
    public async Task<int> Reprocess(InvoiceSettings config,int weekend,CancellationToken token)
    {
        await using var db=factory.Create();var pending=await db.InvoiceRecords.Where(r=>r.Status=="Review").OrderBy(r=>r.Id).Take(50).ToArrayAsync(token);int count=0;
        foreach(var r in pending){var original=Data(r);var templates=config.Templates.Where(t=>t.Sender.Equals(original.Sender,StringComparison.OrdinalIgnoreCase)&&(t.SubjectContains.Length==0||original.Subject.Contains(t.SubjectContains,StringComparison.OrdinalIgnoreCase))).ToArray();var template=templates.Length==1?templates[0]:null;var d=InvoiceRecognition.Parse(new(original.RawText,original.Extraction,original.OcrConfidence,original.ExtractionError),original.Sender,original.Subject,original.ReceivedUtc,template,weekend);d.SenderAuthenticated=original.SenderAuthenticated;d.SenderDateUtc=original.SenderDateUtc;d.MailBody=original.MailBody;
            if(!d.SenderAuthenticated||!config.AllowedSenders.Contains(d.Sender,StringComparer.OrdinalIgnoreCase))d.Issues=d.Issues.Append("Отправитель не подтверждён для автоматической обработки").ToArray();
            if(d.RecurringCandidateId==null)d.RecurringCandidateId=original.RecurringCandidateId;if(d.RecurringCandidateId!=null)d.Issues=d.Issues.Append("Проверьте период повторяющегося платежа").ToArray();
            r.Json=System.Text.Json.JsonSerializer.Serialize(d,RemoteData.Json);r.Revision++;await db.SaveChangesAsync(token);var business=InvoiceRecognition.BusinessKey(d);var copies=business==""?[]:await db.InvoiceRecords.AsNoTracking().Where(x=>x.Id!=r.Id&&x.BusinessKey==business).ToArrayAsync(token);
            if(copies.Length>0&&!copies.Any(x=>{var old=Data(x);return old.BankAccount==d.BankAccount&&old.BankCode==d.BankCode;})){d.Issues=d.Issues.Append("Тот же счёт с другими реквизитами: проверьте вручную").ToArray();r.Json=System.Text.Json.JsonSerializer.Serialize(d,RemoteData.Json);await db.SaveChangesAsync(token);}
            if(d.Issues.Length==0)await Approve(new(r.Id,r.Revision,d),token);count++;
        }return count;
    }
    public async Task Ignore(int id,int revision,CancellationToken token){await using var db=factory.Create();var r=await db.InvoiceRecords.SingleAsync(x=>x.Id==id,token);if(r.Revision!=revision||r.Status!="Review")throw new InvoiceConflictException(global::SysAdminAssistant.Core.ProductText.Get("Счёт уже обработан"));r.Status="Ignored";r.Revision++;await db.SaveChangesAsync(token);}
    public async Task<InvoiceAttachment> File(int id,CancellationToken token){await using var db=factory.Create();return await db.InvoiceAttachments.AsNoTracking().SingleOrDefaultAsync(a=>a.Id==id,token)??throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Документ не найден"));}
}
